<?php
require_once __DIR__.'/m0/bootstrap.php';
require_once EIPSI_FORMS_PLUGIN_DIR.'includes/assessment-editor/runtime/Owner.php';
require_once EIPSI_FORMS_PLUGIN_DIR.'includes/assessment-editor/PartialProgress.php';
use EIPSI\AssessmentEditor\Definition as D;
use EIPSI\AssessmentEditor\Repository as R;
use EIPSI\AssessmentEditor\Runtime\Owner;
use EIPSI\AssessmentEditor\Runtime\Metadata;
$tests=0;$failures=0;$owned=array();$executions=array();$versions=array();$priorEnabled=get_option('eipsi_native_runtime_enabled',null);$priorLong=get_option('eipsi_study_engine_longitudinal_enabled',null);$priorCron=_get_cron_array();$studyFixtures=array();$now=time();$owner=new Owner(null,static function()use(&$now){return $now;});$owner->store->install();wp_set_current_user(1);
function pr_assert($v,$m='Assertion failed'){if(!$v)throw new RuntimeException($m);}
function pr_reject($fn,$code=null){try{$fn();}catch(Throwable $e){if($code!==null)pr_assert($e->getCode()===$code,$e->getMessage());return $e;}throw new RuntimeException('Expected rejection');}
function pr_test($name,$fn){global $tests,$failures;$tests++;try{$fn();echo "PASS $name\n";}catch(Throwable $e){$failures++;echo "FAIL $name: ".$e->getMessage()."\n";}}
function pr_definition($enabled=true,$type=null){$d=json_decode(file_get_contents(__DIR__.'/assessment-editor/functional-fixture.json'),true);$d['id']='AE_'.bin2hex(random_bytes(12));$d['flow']['pages']=array();$d['flow']['save_continue']['enabled']=$enabled;$d['flow']['metadata_profile']='basic';$d['flow']['save_continue']['window']=array('value'=>1,'unit'=>'minutes');if($type)$d['elements']=array_values(array_filter($d['elements'],static function($e)use($type){return $e['type']===$type;}));return D::validate($d);}
function pr_new($enabled=true,$type=null,$custom=null){global $owner,$owned,$versions,$executions;$d=$custom??pr_definition($enabled,$type);$record=R::save($d,0);$owned[]=$d['id'];$v=$owner->publish($d['id'],1);$versions[]=$v['version_id'];$e=$owner->assign($v['version_id'],array('kind'=>'WORDPRESS_USER','user_id'=>1));$executions[]=$e['execution_id'];return $owner->view($e['execution_id']);}
function pr_meta($f){return array('contract'=>'NATIVE_PROCESS_V1','assessment_id'=>$f['definition']['id'],'definition_ref'=>array(),'started_at'=>1000,'completed_at'=>null,'duration'=>0,'status'=>'active','recovery_used'=>false,'recovery_count'=>0,'pages'=>array(),'items'=>array(),'events'=>array(),'dropped_events'=>0);}
function pr_command($f,$action='partial',$answers=array(),$touched=array(),$metadata=null){return array('action'=>$action,'command_id'=>'NC_'.bin2hex(random_bytes(10)),'revision'=>$f['revision'],'version_id'=>$f['version_id'],'csrf'=>$f['csrf'],'answers'=>$answers,'touched'=>$touched,'metadata'=>$metadata??pr_meta($f));}
function pr_answers($d){$answers=array();$touched=array();$walk=function($items)use(&$walk,&$answers,&$touched){foreach($items as $e){$type=$e['type'];$key=$e['response_key'];if($type==='matrix'){foreach($e['properties']['matrix_rows'] as $r)$answers[$r['response_key']]=$e['options'][2]['id'];}elseif($key){$value='Respuesta final';if($type==='date')$value='2026-10-09';elseif($type==='url')$value='https://example.test/';elseif($type==='email')$value='test@example.test';elseif(in_array($type,array('number','vas'),true))$value=$type==='vas'?$e['properties']['initial']:2;elseif($type==='multiple_choice')$value=array_column(array_slice($e['options'],0,2),'id');elseif(in_array($type,array('likert','select','single_choice'),true))$value=$e['options'][count($e['options'])-1]['id'];$answers[$key]=$value;if($type==='vas')$touched[$key]=true;}$walk($e['children']);}};$walk($d['elements']);return array($answers,$touched);}
function pr_complete($f,$answers=null,$touched=null){global $owner;if($answers===null)list($answers,$touched)=pr_answers($f['definition']);while($f['page']<count($f['definition']['flow']['pages'])-1)$f=$owner->command($f['execution_id'],pr_command($f,'next',$answers,$touched));return $owner->command($f['execution_id'],pr_command($f,'submit',$answers,$touched));}
function pr_random_definition($count=2,$order='random'){$d=json_decode(file_get_contents(__DIR__.'/assessment-editor/randomization-fixture.json'),true);$d['id']='AE_'.bin2hex(random_bytes(12));$d['elements'][0]['properties']['count']=$count;$d['elements'][0]['properties']['order']=$order;$d['flow']['save_continue']['window']=array('value'=>1,'unit'=>'minutes');return D::validate($d);}
function pr_random_answers($f){$d=\EIPSI\AssessmentEditor\Randomization::apply($f['definition'],$f['randomization']);return pr_answers($d);}
try{
pr_test('Editable question messages agree with server validation including VAS and matrix',function(){
 $d=pr_definition(true,'text');$d['elements'][0]['properties']['required']=true;$d['elements'][0]['properties']['required_message']='Completá este dato';$d['elements'][0]['properties']['validation_message']='Formato propio';$d['elements'][0]['properties']['length_message']='Longitud propia';$d['elements'][0]['properties']['min_length']=4;$d=D::validate($d);$key=$d['elements'][0]['response_key'];$errors=\EIPSI\AssessmentEditor\Answers::errors($d,array());pr_assert($errors[0]['message']==='Completá este dato');$errors=\EIPSI\AssessmentEditor\Answers::errors($d,array($key=>'a'));pr_assert($errors[0]['message']==='Longitud propia');$d['elements'][0]['properties']['required_message']='';pr_assert(count(\EIPSI\AssessmentEditor\Answers::errors($d,array()))===1,'Blank message bypassed required validation');
});
pr_test('General message configuration round trips and rejects invalid message types',function(){
 $d=pr_definition(true,'text');$d['flow']['messages']=array('progress'=>'Paso [ACTUAL] / [TOTAL]','discarded'=>'Listo');$d=D::validate($d);pr_assert($d['flow']['messages']['discarded']==='Listo');$d['flow']['messages']['discarded']=array('bad');pr_reject(function()use($d){D::validate($d);});
});
pr_test('Foreign browser entry creates isolated attempt and returns to its own current attempt',function()use($owner,&$executions){
 $f=pr_new(true,'text');$before=$owner->store->find('executions',$f['execution_id']);wp_set_current_user(0);unset($_COOKIE['eipsi_assessment_session']);try{$entry=$owner->pageEntry($f['execution_id']);parse_str(parse_url($entry['redirect'],PHP_URL_QUERY),$q);$id=$q['eipsi_native'];$executions[]=$id;$new=$owner->view($id);pr_assert($new['session']===null&&$new['state']==='ACTIVE');pr_assert($owner->pageEntry($id)['execution_id']===$id);pr_assert($owner->pageEntry($f['execution_id'])['redirect']===$entry['redirect']);pr_assert($owner->store->find('executions',$f['execution_id'])===$before);}finally{wp_set_current_user(1);}
});
pr_test('Multiple choice count messages agree for absent partial and excessive selections',function(){
 $d=pr_definition();$q=null;foreach($d['elements'] as $item)if($item['type']==='multiple_choice')$q=$item;if(!$q){$q=$d['elements'][0];$q['type']='multiple_choice';$q['properties']=array('label'=>'Elegí','helper'=>'','required'=>true,'variable_name'=>'choice','label_html'=>null,'helper_html'=>null,'footer_html'=>'','columns'=>1,'min_selected'=>2,'max_selected'=>2,'presentation'=>'vertical');$q['options']=array(array('id'=>'O_A','label'=>'A'),array('id'=>'O_B','label'=>'B'),array('id'=>'O_C','label'=>'C'));}
 $q['properties']=array_merge($q['properties'],array('required'=>true,'min_selected'=>2,'max_selected'=>2,'required_message'=>'Obligatorio','validation_message'=>'NO USAR','selection_min_message'=>'Mínimo [MINIMO]','selection_max_message'=>'Máximo [MAXIMO]'));$q['options']=array(array('id'=>'O_A','label'=>'A'),array('id'=>'O_B','label'=>'B'),array('id'=>'O_C','label'=>'C'));$d['elements']=array($q);$d['flow']['pages']=array();$d=D::validate($d);$key=$q['response_key'];foreach(array(array(),array($key=>array()),array($key=>array('O_A'))) as $answers){$errors=\EIPSI\AssessmentEditor\Answers::errors($d,$answers);pr_assert($errors[0]['message']==='Mínimo 2');}$errors=\EIPSI\AssessmentEditor\Answers::errors($d,array($key=>array('O_A','O_B','O_C')));pr_assert($errors[0]['message']==='Máximo 2');pr_assert(!\EIPSI\AssessmentEditor\Answers::errors($d,array($key=>array('O_A','O_B'))));$q['properties']['min_selected']=0;$d['elements']=array($q);$errors=\EIPSI\AssessmentEditor\Answers::errors($d,array());pr_assert($errors[0]['message']==='Obligatorio');
});
pr_test('Numeric invalid text uses validation message and only empty input uses required message',function(){
 $d=pr_definition(true,'text');$q=&$d['elements'][0];$q['type']='number';$q['properties']=array_intersect_key($q['properties'],array_flip(array('label','helper','required','variable_name','label_html','helper_html','footer_html')))+array('placeholder'=>'','min'=>null,'max'=>null,'step'=>1,'integer_only'=>false);$q['properties']['required']=true;$q['properties']['required_message']='Falta respuesta';$q['properties']['validation_message']='Número inválido';$key=$q['response_key'];unset($q);$d=D::validate($d);foreach(array('abc','1e','-','.','0x10','1e9999') as $raw){$errors=\EIPSI\AssessmentEditor\Answers::errors($d,array($key=>$raw));pr_assert($errors[0]['message']==='Número inválido');}$errors=\EIPSI\AssessmentEditor\Answers::errors($d,array($key=>null));pr_assert($errors[0]['message']==='Falta respuesta');$d['elements'][0]['properties']['required']=false;pr_assert(!\EIPSI\AssessmentEditor\Answers::errors($d,array($key=>null)));$errors=\EIPSI\AssessmentEditor\Answers::errors($d,array($key=>'abc'));pr_assert($errors[0]['message']==='Número inválido');
});
pr_test('Remaining control messages validate and server uses multiline date and unknown-key messages',function(){
 $d=pr_definition(true,'text');$q=&$d['elements'][0];$q['type']='textarea';$q['properties']['rows']=3;$q['properties']['content_type']='free';$q['properties']['display_mode']='multiline';$q['properties']['min_length']=3;$q['properties']['max_length']=5;$q['properties']['length_message']='Entre [MINIMO] y [MAXIMO]';$key=$q['response_key'];unset($q);$d=D::validate($d);foreach(array('a'=>'Entre 3 y 5','abcdef'=>'Entre 3 y 5') as $answer=>$message){$errors=\EIPSI\AssessmentEditor\Answers::errors($d,array($key=>$answer));pr_assert($errors[0]['message']===$message);}$d['flow']['messages']['invalid']='Error general propio';$errors=\EIPSI\AssessmentEditor\Answers::errors($d,array('BAD_KEY'=>'x'));pr_assert(end($errors)['message']==='Error general propio');$errors=\EIPSI\AssessmentEditor\Answers::errors($d,array($key=>array('malformed')));pr_assert($errors[0]['message']==='Error general propio');$d=pr_definition(true,'date');$d['elements'][0]['properties']['invalid_value_message']='Fecha propia';$d['elements'][0]['properties']['date_month_names']='A|B';pr_reject(function()use($d){D::validate($d);});$d['elements'][0]['properties']['date_month_names']='A|B|C|D|E|F|G|H|I|J|K|L';$d=D::validate($d);$errors=\EIPSI\AssessmentEditor\Answers::errors($d,array($d['elements'][0]['response_key']=>'invalid'));pr_assert($errors[0]['message']==='Fecha propia');
});
pr_test('Combined text limits numeric range and date format are validated on the server',function(){
 foreach(array('text','textarea','email','tel','url') as $type){$d=pr_definition(true,'text');$q=&$d['elements'][0];$q['type']=$type;$q['properties']['content_type']=in_array($type,array('email','tel','url'),true)?$type:'free';if($type==='textarea'){$q['properties']['rows']=3;$q['properties']['display_mode']='multiline';}$q['properties']['min_length']=3;$q['properties']['max_length']=5;$q['properties']['length_message']='Entre [MINIMO] - [MAXIMO]';$key=$q['response_key'];unset($q);foreach(array('a','abcdef') as $answer){$errors=\EIPSI\AssessmentEditor\Answers::errors($d,array($key=>$answer));pr_assert($errors[0]['message']==='Entre 3 - 5');}}
 $d=pr_definition(true,'text');$q=&$d['elements'][0];$q['type']='number';$q['properties']=array_intersect_key($q['properties'],array_flip(array('label','helper','required','variable_name','label_html','helper_html','footer_html')))+array('placeholder'=>'','min'=>0,'max'=>10,'step'=>1,'integer_only'=>false,'number_range_message'=>'Entre [MINIMO] - [MAXIMO]');$key=$q['response_key'];unset($q);pr_assert(!\EIPSI\AssessmentEditor\Answers::errors($d,array($key=>2.5)));foreach(array(-1,11) as $v){$errors=\EIPSI\AssessmentEditor\Answers::errors($d,array($key=>$v));pr_assert($errors[0]['message']==='Entre 0 - 10');}
 $d=pr_definition(true,'date');foreach(array('DD/MM/YYYY','MM/DD/YYYY','YYYY-MM-DD') as $format){$d['elements'][0]['properties']['date_format']=$format;D::validate($d);}$d['elements'][0]['properties']['date_format']='invalid';pr_reject(function()use($d){D::validate($d);});
});
pr_test('Discard requires the published opt-in and validates boolean policy',function()use($owner){$f=pr_new(true,'text');pr_reject(function()use($owner,$f){$owner->command($f['execution_id'],pr_command($f,'discard'));},409);$d=pr_definition();$d['flow']['allow_discard']='yes';pr_reject(function()use($d){D::validate($d);});});
pr_test('Discard clears current and saved partials atomically with stale-tab and idempotency protection',function()use($owner,&$now){$d=pr_definition(true,'text');$d['flow']['allow_discard']=true;$f=pr_new(true,'text',$d);list($a,$t)=pr_answers($d);$f=$owner->command($f['execution_id'],pr_command($f,'partial',$a,$t));$now+=61;$f=$owner->view($f['execution_id']);pr_assert($f['previous_partial_saved']);$q=pr_command($f,'discard');$f=$owner->command($f['execution_id'],$q);pr_assert($f['state']==='ACTIVE'&&$f['session']===null&&$f['page']===0&&!$f['previous_partial_saved']);pr_reject(function()use($owner,$f){$owner->export($f['execution_id']);},409);$again=$owner->command($f['execution_id'],$q);pr_assert($again['revision']===$f['revision']);$stale=$q;$stale['command_id']='NC_STALE_DISCARD';pr_reject(function()use($owner,$f,$stale){$owner->command($f['execution_id'],$stale);},409);});
pr_test('Discard removes only the current final answer and allows a fresh session',function()use($owner){global $executions;$d=pr_definition(true,'text');$d['flow']['allow_discard']=true;$f=pr_new(true,'text',$d);$done=pr_complete($f);$assigned=$owner->assign($f['version_id'],array('kind'=>'WORDPRESS_USER','user_id'=>1));$executions[]=$assigned['execution_id'];$other=$owner->view($assigned['execution_id']);pr_complete($other);$r=$owner->command($done['execution_id'],pr_command($done,'discard'));$row=$owner->store->find('executions',$done['execution_id']);pr_assert($row['final_json']===null&&$row['completed_at']===null&&$row['metadata_json']===null);pr_assert($owner->store->find('executions',$other['execution_id'])['state']==='COMPLETED');$opened=$owner->command($r['execution_id'],pr_command($r,'open'));pr_assert($opened['session']['answers']===array());pr_assert(pr_complete($opened)['state']==='COMPLETED');});
pr_test('Library edit/load preserves canonical draft revision counters and identities',function()use(&$owned){$d=pr_definition();$owned[]=$d['id'];$r=R::save($d,0);pr_assert(D::json(R::load($d['id']))===D::json($r));});
pr_test('Library duplicate renews Assessment item option row label and page IDs without changing source',function()use(&$owned){$d=pr_definition();$owned[]=$d['id'];$r=R::save($d,0);$copy=R::duplicate($d['id'],1);$owned[]=$copy['definition']['id'];pr_assert(D::json(R::load($d['id']))===D::json($r));pr_assert($copy['definition']['id']!==$d['id']);pr_assert(array_column($copy['definition']['elements'],'id')!==array_column($d['elements'],'id'));pr_assert(array_column($copy['definition']['flow']['pages'],'id')!==array_column($d['flow']['pages'],'id'));pr_assert(array_column($copy['definition']['elements'],'response_key')!==array_column($d['elements'],'response_key'));pr_assert($copy['definition']['elements'][1]['options'][0]['id']!==$d['elements'][1]['options'][0]['id']);pr_assert($copy['definition']['elements'][2]['properties']['matrix_rows'][0]['response_key']!==$d['elements'][2]['properties']['matrix_rows'][0]['response_key']);pr_assert(array_column(array_column($copy['definition']['elements'],'properties'),'variable_name')===array_column(array_column($d['elements'],'properties'),'variable_name'));});
pr_test('Library duplicate rejects stale revision and unauthenticated owner',function()use(&$owned){$d=pr_definition();$owned[]=$d['id'];R::save($d,0);pr_reject(function()use($d){R::duplicate($d['id'],2);},409);wp_set_current_user(0);try{pr_reject(function()use($d){R::duplicate($d['id'],1);},403);}finally{wp_set_current_user(1);}});
pr_test('Library delete removes draft and authoring partials of all admins',function()use(&$owned){$d=pr_definition(true,'text');$owned[]=$d['id'];R::save($d,0);\EIPSI\AssessmentEditor\PartialProgress::save($d,array(),array(),0,array());R::delete($d['id'],1);pr_reject(function()use($d){R::load($d['id']);},404);pr_assert(\EIPSI\AssessmentEditor\PartialProgress::resume($d)===null);});
pr_test('Library delete rejects stale or published references',function()use($owner){$f=pr_new();pr_reject(function()use($f){R::delete($f['definition']['id'],2);},409);pr_reject(function()use($f){R::delete($f['definition']['id'],1);},409);pr_assert($owner->view($f['execution_id'])['version_id']===$f['version_id']);});
pr_test('Publishing requires exact draft revision and admin capability',function()use($owner,&$owned){$d=pr_definition();$owned[]=$d['id'];R::save($d,0);pr_reject(function()use($owner,$d){$owner->publish($d['id'],2);},409);wp_set_current_user(0);try{pr_reject(function()use($owner,$d){$owner->publish($d['id'],1);},403);}finally{wp_set_current_user(1);}});
pr_test('Published immutable snapshot ignores later mutable draft edits',function()use($owner){$f=pr_new();$d=$f['definition'];$d['title']='Edited later';R::save($d,1);$again=$owner->view($f['execution_id']);pr_assert($again['definition']['title']===$f['definition']['title']&&$again['definition_hash']===$f['definition_hash']);});
pr_test('Native version hash detects tampering before any execution response',function()use($owner){$f=pr_new();$v=$owner->store->find('versions',$f['version_id']);$owner->store->db->query($owner->store->prepare('UPDATE '.$owner->store->table('versions').' SET definition_hash=%s WHERE id=%s',str_repeat('0',64),$f['version_id']));try{pr_reject(function()use($owner,$f){$owner->view($f['execution_id']);},409);}finally{$owner->store->db->query($owner->store->prepare('UPDATE '.$owner->store->table('versions').' SET definition_hash=%s WHERE id=%s',$v['definition_hash'],$f['version_id']));}});
pr_test('Retired snapshot refuses future assignment and participant access',function()use($owner){$f=pr_new();$owner->retire($f['version_id']);pr_reject(function()use($owner,$f){$owner->view($f['execution_id']);},403);pr_reject(function()use($owner,$f){$owner->assign($f['version_id'],array('kind'=>'WORDPRESS_USER','user_id'=>1));},409);});
pr_test('URL possession without session never grants native access',function()use($owner){$f=pr_new();wp_set_current_user(0);try{pr_reject(function()use($owner,$f){$owner->view($f['execution_id']);},403);}finally{wp_set_current_user(1);}});
pr_test('Other logged in user cannot read or update native execution',function()use($owner){$f=pr_new();$uid=wp_create_user('native-other-'.bin2hex(random_bytes(4)),bin2hex(random_bytes(20)),'other-'.bin2hex(random_bytes(4)).'@example.test');try{wp_set_current_user($uid);pr_reject(function()use($owner,$f){$owner->view($f['execution_id']);},403);pr_reject(function()use($owner,$f){$owner->command($f['execution_id'],pr_command($f));},403);}finally{wp_set_current_user(1);require_once ABSPATH.'wp-admin/includes/user.php';wp_delete_user($uid);}});
pr_test('Participant mutation requires valid session CSRF and exact version binding',function()use($owner){$f=pr_new();$q=pr_command($f);$q['csrf']='invalid';pr_reject(function()use($owner,$f,$q){$owner->command($f['execution_id'],$q);},403);$q=pr_command($f);$q['version_id']='NV_OTHER';pr_reject(function()use($owner,$f,$q){$owner->command($f['execution_id'],$q);},409);});
pr_test('Partial saving OFF persists temporary session but no permanent response',function()use($owner){$f=pr_new(false);list($a,$t)=pr_answers($f['definition']);$r=$owner->command($f['execution_id'],pr_command($f,'next',$a,$t));$row=$owner->store->find('executions',$f['execution_id']);pr_assert($row['partial_json']!==null&&$row['expires_at']!==null&&$row['final_json']===null&&$r['page']===1&&D::json($r['session']['answers'])===D::json($a));});
pr_test('Partial saving OFF reopens still-valid session with previous page and answers',function()use($owner){$f=pr_new(false);list($a,$t)=pr_answers($f['definition']);$r=$owner->command($f['execution_id'],pr_command($f,'next',$a,$t));$r=$owner->command($r['execution_id'],pr_command($r,'open'));pr_assert($r['page']===1&&D::json($r['session']['answers'])===D::json($a));});
pr_test('Save Continue ON persists exact native answers touched page metadata and snapshot',function()use($owner){$f=pr_new();list($a,$t)=pr_answers($f['definition']);$r=$owner->command($f['execution_id'],pr_command($f,'next',$a,$t));pr_assert(D::json($r['partial']['answers'])===D::json($a)&&$r['partial']['touched']===$t&&$r['partial']['page']===1&&$r['partial']['version_id']===$r['version_id']);pr_assert($r['metadata']['definition_ref']['version_id']===$r['version_id']);});
pr_test('Native questionnaire session expiry renews on activity',function()use($owner,&$now){$f=pr_new();$r=$owner->command($f['execution_id'],pr_command($f));$expires=$r['expires_at'];$now+=20;$r=$owner->command($f['execution_id'],pr_command($r));pr_assert($r['expires_at']===$expires+20);});
pr_test('Native expiry deletes partial answers metadata and page with CAS increment',function()use($owner,&$now){$f=pr_new();$r=$owner->command($f['execution_id'],pr_command($f));$rev=$r['revision'];$now=$r['expires_at'];$r=$owner->view($f['execution_id']);pr_assert($r['partial']===null&&$r['metadata']===null&&$r['page']===0&&$r['revision']===$rev+1);});
pr_test('Native cleanup is idempotent and deletes only expired own records',function()use($owner,&$now){$f=pr_new();$r=$owner->command($f['execution_id'],pr_command($f));$now=$r['expires_at'];pr_assert($owner->cleanup()>=1);pr_assert($owner->cleanup()===0);pr_assert($owner->view($f['execution_id'])['partial']===null);});
pr_test('Recovered ordinary attempt exposes the original Back boundary to the participant',function()use($owner){$d=pr_definition();$d['flow']['allow_back']=true;$f=pr_new(true,null,$d);list($a,$t)=pr_answers($d);$next=$owner->command($f['execution_id'],pr_command($f,'next',$a,$t));pr_assert($next['page']===1&&$next['logical_entry_page']===0,'Ordinary second page hides Back by claiming it is the entry page');$recovered=$owner->view($f['execution_id']);pr_assert($recovered['page']===1&&$recovered['logical_entry_page']===0,'Recovery moved the Back boundary');$back=$owner->command($recovered['execution_id'],pr_command($recovered,'back',$a,$t));pr_assert($back['page']===0&&$back['execution_id']===$f['execution_id'],'Back changed attempt');});
