pr_test('Study anonymous ownership uses existing recovery cookie and revocation',function()use($owner,&$studyFixtures,&$executions,&$versions){require_once EIPSI_FORMS_PLUGIN_DIR.'includes/study-engine/content.php';require_once __DIR__.'/study-engine/cross-sectional/support.php';$p=pe_publish();$studyFixtures[]=$p['definition']['study']['logical_id'];$parent=pe_runtime()->handle($p['public']);$native=pr_new();$binding=array('kind'=>'STUDY_ANONYMOUS','public_id'=>$p['public'],'execution_id'=>$parent['access']['execution_id'],'study_version_id'=>$parent['access']['study_version_id'],'participant_id'=>$parent['access']['id']);$e=$owner->assign($native['version_id'],$binding);$executions[]=$e['execution_id'];$cookie=\EIPSI\StudyEngine\Runtime\AnonymousAccess::cookieName($p['public']);$_COOKIE[$cookie]=$parent['token'];try{$f=$owner->view($e['execution_id']);$r=$owner->command($e['execution_id'],pr_command($f));pr_assert($r['partial']!==null);(new \EIPSI\StudyEngine\Runtime\AnonymousAccess($owner->store->db))->revoke($parent['access']['id']);pr_reject(function()use($owner,$e){$owner->view($e['execution_id']);},403);}finally{unset($_COOKIE[$cookie]);}});
pr_test('Study longitudinal ownership uses existing participant session and logout',function()use($owner,&$studyFixtures,&$executions){require_once EIPSI_FORMS_PLUGIN_DIR.'includes/study-engine/longitudinal.php';require_once __DIR__.'/study-engine/longitudinal/support.php';$GLOBALS['pf_now']=gmdate('Y-m-d\TH:i:s\Z');$p=pf_publish();$studyFixtures[]=$p['definition']['study']['logical_id'];$parent=pf_enroll($p,'native-test@example.test');$native=pr_new();$binding=array('kind'=>'STUDY_SESSION','public_id'=>$p['public'],'execution_id'=>$parent['access']['execution_id'],'study_version_id'=>$parent['access']['study_version_id'],'participant_id'=>$parent['access']['participant_id']);$e=$owner->assign($native['version_id'],$binding);$executions[]=$e['execution_id'];$class='EIPSI\\StudyEngine\\Longitudinal\\Identity';$cookie=$class::cookieName($p['public']);$_COOKIE[$cookie]=$parent['token'];try{$f=$owner->view($e['execution_id']);pr_assert($owner->command($e['execution_id'],pr_command($f))['partial']!==null);(new $class($owner->store->db))->logout($p['public'],$parent['token']);pr_reject(function()use($owner,$e){$owner->view($e['execution_id']);},403);}finally{unset($_COOKIE[$cookie]);}});
pr_test('Native Study DO_NOT_USE cleanup joins parent transaction and erases only linked native data',function()use($owner,&$studyFixtures,&$executions){require_once EIPSI_FORMS_PLUGIN_DIR.'includes/assessment-editor/runtime/Privacy.php';$p=pe_publish();$studyFixtures[]=$p['definition']['study']['logical_id'];$parent=pe_runtime()->handle($p['public']);$native=pr_new(true,'text');$e=$owner->assign($native['version_id'],array('kind'=>'STUDY_ANONYMOUS','public_id'=>$p['public'],'execution_id'=>$parent['access']['execution_id'],'study_version_id'=>$parent['access']['study_version_id'],'participant_id'=>$parent['access']['id']));$executions[]=$e['execution_id'];$cookie=\EIPSI\StudyEngine\Runtime\AnonymousAccess::cookieName($p['public']);$_COOKIE[$cookie]=$parent['token'];try{$f=$owner->view($e['execution_id']);pr_complete($f);$db=$owner->store->db;$db->transactional(function()use($db,$parent){$db->update('study_executions',array('data_policy'=>'DO_NOT_USE'),$db->prepare('id=%s',$parent['access']['execution_id']));\EIPSI\AssessmentEditor\Runtime\Privacy::eraseStudy($db,$parent['access']['execution_id']);});$row=$owner->store->find('executions',$e['execution_id']);pr_assert($row['state']==='REDACTED'&&$row['final_json']===null&&$row['metadata_json']===null);pr_assert($owner->store->find('executions',$native['execution_id'])['state']==='ACTIVE');}finally{unset($_COOKIE[$cookie]);}});
