pr_test('Native publication pins local images independently of mutable media source',function()use($owner){$upload=wp_upload_dir();wp_mkdir_p($upload['basedir']);$name='native-test-'.bin2hex(random_bytes(5)).'.png';$file=$upload['basedir'].'/'.$name;$bytes=base64_decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+j6XcAAAAASUVORK5CYII=');file_put_contents($file,$bytes);$pin=$upload['basedir'].'/eipsi-native-media/'.hash('sha256',$bytes).'.png';$existed=file_exists($pin);try{$d=pr_definition(true,'text');$d['flow']['completion']['image_url']=$upload['baseurl'].'/'.$name;$f=pr_new(true,'text',$d);pr_assert(strpos($f['definition']['flow']['completion']['image_url'],'eipsi_native_asset=')!==false);file_put_contents($file,'changed source');pr_assert($owner->view($f['execution_id'])['definition_hash']===$f['definition_hash']);}finally{unlink($file);if(!$existed&&file_exists($pin))unlink($pin);}});
