pr_test('Two actual PHP processes race one revision without last-write-wins',function()use($owner){$f=pr_new(true,'text');$key=$f['definition']['elements'][0]['response_key'];$commands=array(pr_command($f,'partial',array($key=>'Tab one')),pr_command($f,'partial',array($key=>'Tab two')));$dir='/tmp/eipsi-native-race-'.bin2hex(random_bytes(8));mkdir($dir,0700);file_put_contents($dir.'/input.json',json_encode(array('execution_id'=>$f['execution_id'],'commands'=>$commands)));$processes=array();try{foreach(array(0,1) as $slot){$pipes=array();$p=proc_open(array(PHP_BINARY,__DIR__.'/assessment-editor/native-race-worker.php',$dir,(string)$slot),array(0=>array('pipe','r'),1=>array('file',$dir.'/stdout'.$slot,'w'),2=>array('file',$dir.'/stderr'.$slot,'w')),$pipes);pr_assert(is_resource($p));fclose($pipes[0]);$processes[$slot]=$p;}$until=microtime(true)+15;while(!file_exists($dir.'/ready0')||!file_exists($dir.'/ready1')){pr_assert(microtime(true)<$until,'Worker readiness timeout');usleep(10000);}touch($dir.'/start');foreach($processes as $p)pr_assert(proc_close($p)===0,'Worker failed');$processes=array();$results=array(json_decode(file_get_contents($dir.'/result0.json'),true),json_decode(file_get_contents($dir.'/result1.json'),true));pr_assert(count(array_filter($results,static function($r){return $r['ok'];}))===1,'CAS outcomes: '.json_encode($results));$loser=$results[0]['ok']?$results[1]:$results[0];pr_assert($loser['code']===409,'Loser code: '.json_encode($results));$winner=$results[0]['ok']?0:1;pr_assert((new Owner())->view($f['execution_id'])['partial']['answers'][$key]===$commands[$winner]['answers'][$key],'Winner response preserved');}finally{foreach($processes as $p){proc_terminate($p);proc_close($p);}foreach(glob($dir.'/*') as $file)unlink($file);rmdir($dir);}});
pr_test('Native transaction rolls back storage conflicts as 409 without hiding unrelated database failures',function(){
    foreach(array(1020,1205,1213,9999) as $code){
        $store=new \EIPSI\AssessmentEditor\Runtime\Store();
        $store->db=new class {public $queries=array();public function prepare($sql,...$args){global $wpdb;return $wpdb->prepare($sql,...$args);}public function rows($sql){return array(array('ENGINE'=>'InnoDB'),array('ENGINE'=>'InnoDB'),array('ENGINE'=>'InnoDB'));}public function row($sql){return array('active'=>0);}public function query($sql){$this->queries[]=$sql;return 0;}};
        pr_reject(function()use($store,$code){$store->transaction(function()use($code){throw new \EIPSI\StudyEngine\Persistence\DatabaseFailure($code);});},$code===9999?9999:409);
        pr_assert($store->db->queries===array_merge(...array_fill(0,$code===9999?1:3,array('START TRANSACTION','ROLLBACK'))),'Every failed retry must roll back; unrelated failures must not retry');
    }
});
pr_test('Expired session with partial saving ON archives answers without restoring them',function()use($owner,&$now){$f=pr_new(true,'text');$key=$f['definition']['elements'][0]['response_key'];$f=$owner->command($f['execution_id'],pr_command($f,'partial',array($key=>'Previous session')));$now=$f['expires_at'];$fresh=$owner->view($f['execution_id']);pr_assert($fresh['session']===null&&$fresh['page']===0&&$fresh['session_reset']&&$fresh['previous_partial_saved']);$x=$owner->export($f['execution_id']);pr_assert($x['rows'][0]['value']==='Previous session'&&$x['rows'][0]['response_status']==='PARTIAL_SAVED');pr_assert(count($x['saved_partials'])===1);pr_reject(function()use($owner,$x){$owner->view($x['saved_partials'][0]['id']);},403);});
