pr_test('Completed response survives session duration and cleanup without becoming a partial',function()use($owner,&$now){$f=pr_complete(pr_new(true,'text'));$now+=3600;$owner->cleanup();$r=$owner->view($f['execution_id']);pr_assert($r['state']==='COMPLETED'&&!$r['session_reset']);$x=$owner->export($f['execution_id']);pr_assert(!$x['saved_partials']&&$x['rows'][0]['response_status']==='COMPLETED');});
pr_test('Archived partial export retains ownership and version guards',function()use($owner,&$now){$f=pr_new(true,'text');$key=$f['definition']['elements'][0]['response_key'];$f=$owner->command($f['execution_id'],pr_command($f,'partial',array($key=>'Protected')));$now=$f['expires_at'];wp_set_current_user(0);try{pr_reject(function()use($owner,$f){$owner->view($f['execution_id']);},403);pr_reject(function()use($owner,$f){$owner->export($f['execution_id']);},403);}finally{wp_set_current_user(1);}pr_assert($owner->store->find('executions',$f['execution_id'])['partial_json']!==null);$owner->view($f['execution_id']);pr_assert(count($owner->export($f['execution_id'])['saved_partials'])===1);});
pr_test('User privacy erases archived partials as well as current session without touching another owner',function()use($owner,&$now){require_once EIPSI_FORMS_PLUGIN_DIR.'includes/assessment-editor/runtime/Privacy.php';$uid=wp_create_user('session-privacy-'.bin2hex(random_bytes(4)),bin2hex(random_bytes(20)));$f=pr_new(true,'text');$key=$f['definition']['elements'][0]['response_key'];$f=$owner->command($f['execution_id'],pr_command($f,'partial',array($key=>'Archive me')));$now=$f['expires_at'];$owner->view($f['execution_id']);$archive=$owner->export($f['execution_id'])['saved_partials'][0]['id'];foreach(array($f['execution_id'],$archive) as $id)$owner->store->update('executions',array('binding_json'=>D::json(array('kind'=>'WORDPRESS_USER','user_id'=>$uid))),$owner->store->prepare('id=%s',$id));$other=pr_new(true,'text');\EIPSI\AssessmentEditor\Runtime\Privacy::eraseUser($uid);foreach(array($f['execution_id'],$archive) as $id){$row=$owner->store->find('executions',$id);pr_assert($row['state']==='REDACTED'&&$row['final_json']===null&&$row['partial_json']===null);}pr_assert($owner->view($other['execution_id'])['state']==='ACTIVE');require_once ABSPATH.'wp-admin/includes/user.php';wp_delete_user($uid);});

pr_test('Local Randomization validates count mode order pages depth and stable unique identities',function(){
