    $d=pr_random_definition(1);$r=&$d['elements'][0];$questions=$r['children'];$inner=$r;$inner['id']='EL_INNER';$inner['properties']['count']=1;$inner['children']=array_slice($questions,2,2);$group=array('id'=>'EL_GROUP','type'=>'group','response_key'=>null,'properties'=>array('label'=>'Complete unit'),'options'=>array(),'children'=>array_slice($questions,0,2));$r['children']=array($group,$inner);unset($r);$d=D::validate($d);$record=\EIPSI\AssessmentEditor\Randomization::resolve($d,'nested',1000);$resolved=\EIPSI\AssessmentEditor\Randomization::apply($d,$record);pr_assert(count($record['blocks'])===2&&count($resolved['elements'][0]['children'])===1);$selected=$resolved['elements'][0]['children'][0];pr_assert(count($selected['children'])===($selected['id']==='EL_GROUP'?2:1));
